INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt") VALUES ('cms5am35v0007901g8lqs0wav', 'tlp-pipeline', 'cms5am35r0005901gjw01i9tq', 'TLP Pipeline', 'TLP Pipeline S.A.', 'TLP Pipeline develops, builds and operates large-diameter pipeline systems and associated pumping and terminal infrastructure for water, mining concentrates and hydrocarbons across Latin America. The group manages a multi-country project pipeline and procures equipment, EPC capacity and specialized services at scale for its concession portfolio.', 'infrastructure', 'Brazil', 'BR', 'São Paulo', NULL, 1987, 4200, NULL, true, true, '2026-07-28 23:34:33.092', '2026-07-28 23:34:33.092');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt") VALUES ('cms5am366000a901gonfddbnq', 'andrade-gutierrez', 'cms5am3620008901gno7rb711', 'Andrade Gutiérrez', 'Andrade Gutiérrez Engenharia S.A.', 'Andrade Gutiérrez is one of Latin America''s largest engineering and heavy-construction groups, with seven decades of experience delivering mining, energy, sanitation and transport infrastructure across more than 40 countries. Its project teams contract equipment fleets, subcontractors and technical services for concurrent large-scale works.', 'infrastructure', 'Brazil', 'BR', 'Belo Horizonte', NULL, 1948, 18000, NULL, true, true, '2026-07-28 23:34:33.102', '2026-07-28 23:34:33.102');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt") VALUES ('cms5am36d000d901geopp75qf', 'tbea', 'cms5am36a000b901gw529t4x1', 'TBEA', 'TBEA Co., Ltd.', 'TBEA is a global manufacturer of power transmission and transformation equipment and a developer of energy infrastructure, with transformer, cable and polysilicon plants supplying utility-scale projects worldwide. Its international project division sources logistics, civil works and local technical partners for turnkey energy developments.', 'energy', 'China', 'CN', 'Changji', NULL, 1993, 26000, NULL, true, true, '2026-07-28 23:34:33.11', '2026-07-28 23:34:33.11');
INSERT INTO public."CompanyProfile" (id, slug, "userId", name, "legalName", description, sector, country, "countryCode", city, website, founded, employees, "logoUrl", verified, "isAnchor", "createdAt", "updatedAt") VALUES ('cms5am36h000f901go8hq5h4m', 'aldridge-industrial-holdings', 'cms5am3590001901gxvwc1t0y', 'Aldridge Industrial Holdings', 'Aldridge Industrial Holdings Ltd.', 'Diversified industrial holding headquartered in the UAE, with controlling stakes in port terminals, bulk-liquids storage and manufacturing assets across the Middle East and Latin America. The group actively rotates its portfolio and develops greenfield industrial platforms alongside strategic partners.', 'ports', 'United Arab Emirates', 'AE', 'Dubai', NULL, 2004, 1350, NULL, true, false, '2026-07-28 23:34:33.113', '2026-07-28 23:34:33.113');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am37x0014901g40cllxmu', 'andina-drilling-geotech', 'cms5am37t0012901gekn1zp13', 'Andina Drilling & Geotech', 'Chilean drilling and geotechnical services contractor specialized in high-altitude and remote mining environments. Full-service offering from exploration drilling to geotechnical instrumentation, with an owned fleet of 14 rigs and permanent QA/QC and safety teams.', 'technical_services', 'Chile', 'CL', 'Santiago', NULL, 380, 21, '["ISO 9001","ISO 14001","ISO 45001"]', '["68,000 m diamond & RC drilling — Vizcachas Copper Project (2019–2024)","Geotechnical campaign, 240 boreholes — coastal water pipeline (2023)","Dewatering wells program — Salar de Atacama (2021)"]', '14 drill rigs · 3 concurrent remote camps', 'PUBLISHED', true, false, NULL, '2026-07-28 23:34:33.165', '2026-07-28 23:34:33.165');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3840017901g6n9qcfng', 'skanor-epc', 'cms5am3810015901gwxlqozjx', 'Skanor EPC', 'European EPC contractor for water, energy and industrial infrastructure with three decades of international delivery. Strong track record in pumping and compression stations, HV substations and balance-of-plant packages under FIDIC frameworks.', 'epc', 'Spain', 'ES', 'Madrid', NULL, 2100, 34, '["ISO 9001","ISO 45001","FIDIC-experienced"]', '["4 pumping stations delivered EPC — Iberia & North Africa","220/500 kV substations, 11 projects across LatAm","Desalination balance-of-plant, 2 plants in Morocco"]', '3 concurrent EPC sites · 120 engineers in-house', 'PUBLISHED', true, true, NULL, '2026-07-28 23:34:33.173', '2026-07-28 23:34:33.173');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am38a001a901gizpy3v97', 'transandes-heavy-logistics', 'cms5am3870018901gstekj4a8', 'TransAndes Heavy Logistics', 'Heavy-lift and project-cargo specialist covering the Pacific coast and Andean corridors. Integrated route studies, bridge reinforcement, escorted convoys and port handling for out-of-gauge industrial cargo.', 'logistics', 'Chile', 'CL', 'Valparaíso', NULL, 640, 18, '["ISO 9001","ISO 39001","BASC"]', '["Transport of 12 transformers up to 260 t — Andean transmission line","Port-to-mine oversized cargo framework — 3 mining operations","SPMT operations for modular plant relocation (2022)"]', 'SPMT up to 320 t · 60-truck heavy fleet · route engineering team', 'PUBLISHED', true, false, NULL, '2026-07-28 23:34:33.178', '2026-07-28 23:34:33.178');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am38h001d901g0f1cxv3x', 'maquisur-equipment', 'cms5am38d001b901gjh97rwhd', 'MaquiSur Equipment', 'Andean heavy-equipment distributor and maintenance contractor. Sales, leasing and full maintenance-and-repair contracts (MARC) for off-highway fleets, with factory-certified workshops and on-site parts logistics.', 'equipment', 'Peru', 'PE', 'Lima', NULL, 890, 26, '["ISO 9001","OEM-certified dealer","MARC-experienced"]', '["MARC contracts on 4 mining fleets (availability > 89%)","Supply of 55 off-highway trucks to Andean copper operations","On-site parts warehouses at 6 remote operations"]', '5-year MARC programs · on-site technician coverage nationwide', 'PUBLISHED', true, false, NULL, '2026-07-28 23:34:33.185', '2026-07-28 23:34:33.185');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am38m001g901gltu6fx1l', 'verdant-environmental', 'cms5am38j001e901g088sxi77', 'Verdant Environmental', 'Brazilian environmental consultancy focused on ports, coastal works and heavy infrastructure: impact studies, licensing management before state and federal agencies, marine monitoring and community engagement.', 'environmental', 'Brazil', 'BR', 'Rio de Janeiro', NULL, 210, 15, '["IBAMA-registered","ISO 14001"]', '["EIA and licensing — 2 container terminal expansions (Santos, Itajaí)","Marine biota monitoring, 5-year program — port dredging","Community engagement programs for 8 infrastructure projects"]', '40 licensed specialists · marine monitoring vessels on retainer', 'PUBLISHED', true, false, NULL, '2026-07-28 23:34:33.191', '2026-07-28 23:34:33.191');
INSERT INTO public."SupplierProfile" (id, slug, "userId", name, description, category, country, "countryCode", city, website, employees, "yearsActive", certifications, portfolio, capacity, status, verified, featured, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am38s001j901gizc2gxk8', 'omnigrid-om', 'cms5am38p001h901gv1ihbpuo', 'OmniGrid O&M', 'Independent operations & maintenance provider for utility-scale solar plants and HV infrastructure. Preventive and corrective programs, certified switching personnel and CMMS-based performance reporting.', 'maintenance', 'Mexico', 'MX', 'Monterrey', NULL, 460, 12, '["ISO 55001","NFPA 70E","Certified HV switching crews"]', '["O&M of 520 MW PV portfolio across Mexico and Argentina","HV substation maintenance framework — 14 substations","24/7 monitoring center with CMMS reporting"]', '520 MW under management · 24/7 NOC · thermography drones', 'PUBLISHED', true, false, NULL, '2026-07-28 23:34:33.196', '2026-07-28 23:34:33.196');
