INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am36m000h901gddwpzkeq', 'tlp-large-diameter-pipe-supply', 'Large-diameter steel pipe supply — 180 km water transport line', 'Supply of API 5L X70 welded steel pipe (48–56 inch) with internal lining and external coating for a 180 km desalinated-water transport system in northern Chile. Staged deliveries over 22 months to two laydown yards; mill certificates and third-party inspection required for every heat.', 'equipment', 'STANDARD', 'cms5am35v0007901g8lqs0wav', 'Chile', 'CL', 'Antofagasta', 60000000, 85000000, '2026-10-15 00:00:00', '["API 5L PSL2 mill certification","Proven deliveries above 100 km of pipeline in the last 10 years","Third-party inspection (TPI) acceptance at mill","Staged delivery plan with two laydown yards"]', 'OPEN', 350, '2026-07-28 23:34:33.119', '2026-07-28 23:34:33.119');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am36u000j901gb1wfl94l', 'tlp-epc-pumping-stations', 'EPC contractor for three 12 MW pumping stations', 'Engineering, procurement and construction of three high-head pumping stations (12 MW installed each) including electrical rooms, surge protection and SCADA integration for a concentrate pipeline in Peru. Contract under FIDIC Yellow Book with milestone-based payments.', 'epc', 'EPC_TENDER', 'cms5am35v0007901g8lqs0wav', 'Peru', 'PE', 'Arequipa', 90000000, 140000000, '2026-11-30 00:00:00', '["FIDIC Yellow Book track record","At least two pumping or compression stations delivered as EPC","In-country civil works capacity (Peru)","ISO 9001 / ISO 45001 certified"]', 'OPEN', 227, '2026-07-28 23:34:33.126', '2026-07-28 23:34:33.126');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am36y000l901g9a7h12rd', 'tlp-oversize-logistics', 'Specialized logistics for oversized pipeline components', 'Multi-year framework for port handling, storage and overland transport of oversized pipeline components (up to 90 t single pieces) from Brazilian and Chilean ports to Andean job sites, including route studies, permits and escorted convoys.', 'logistics', 'STANDARD', 'cms5am35v0007901g8lqs0wav', 'Brazil', 'BR', 'Santos', 8000000, 15000000, '2026-09-30 00:00:00', '["Heavy-lift fleet above 80 t payload","Cross-border Andean transport experience","Cargo insurance up to USD 20M per shipment"]', 'OPEN', 203, '2026-07-28 23:34:33.13', '2026-07-28 23:34:33.13');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am372000n901g1ln7cg6k', 'ag-earthworks-subcontractor-iron-ore', 'Earthworks & haulage subcontractor — iron ore mine expansion', 'Mass earthworks subcontract (34 Mm³ over 30 months) for an iron ore expansion in Minas Gerais: drilling support, load & haul, haul-road maintenance and dust control. Own fleet required; fuel supplied by the main contractor at site.', 'construction', 'STANDARD', 'cms5am366000a901gonfddbnq', 'Brazil', 'BR', 'Belo Horizonte', 25000000, 40000000, '2026-10-01 00:00:00', '["Own fleet of at least 30 haul units","Mining earthworks experience above 20 Mm³","Safety statistics (TRIFR) below industry benchmark"]', 'OPEN', 414, '2026-07-28 23:34:33.134', '2026-07-28 23:34:33.134');
