INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37a000r901gkhzvlo1d', 'ag-environmental-licensing-port', 'Environmental licensing consultancy for port expansion works', 'Environmental impact studies, licensing management and community-engagement program for a container terminal expansion, including dredging permits and marine biota monitoring plans coordinated with state and federal agencies.', 'environmental', 'STANDARD', 'cms5am366000a901gonfddbnq', 'Brazil', 'BR', 'Santos', 2000000, 5000000, '2026-09-15 00:00:00', '["Port or coastal EIA experience in Brazil","Registered with IBAMA as consultant","Marine biota monitoring capability"]', 'OPEN', 90, '2026-07-28 23:34:33.142', '2026-07-28 23:34:33.142');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37e000t901gt1lap9mv', 'tbea-epc-substation-partner', 'Local EPC partner for 500 kV substation packages in LatAm', 'TBEA seeks local EPC partners in Chile and Argentina for the balance-of-plant and installation scope of 500 kV substation packages (civil works, erection, testing support) tied to transmission projects where TBEA supplies main transformers and HV equipment.', 'epc', 'STANDARD', 'cms5am36d000d901geopp75qf', 'Chile', 'CL', 'Santiago', 30000000, 60000000, '2026-11-15 00:00:00', '["HV substation erection references (220 kV or above)","Local electrical contractor licenses","Capacity for two concurrent sites"]', 'OPEN', 42, '2026-07-28 23:34:33.146', '2026-07-28 23:34:33.146');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37h000v901go780ru17', 'tbea-transformer-logistics', 'Port-to-site logistics for power transformer deliveries', 'Framework agreement for reception, port handling and inland transport of large power transformers (up to 280 t) from Manzanillo port to project sites in central Mexico, including hydraulic platform trailers, route reinforcement works and cranage.', 'logistics', 'STANDARD', 'cms5am36d000d901geopp75qf', 'Mexico', 'MX', 'Manzanillo', 5000000, 12000000, '2026-10-30 00:00:00', '["Hydraulic modular trailers (SPMT) above 250 t","Transformer transport references","Route survey and bridge reinforcement capability"]', 'OPEN', 48, '2026-07-28 23:34:33.149', '2026-07-28 23:34:33.149');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37k000x901gwq9yuzat', 'tbea-om-solar-services', 'O&M technical services for two utility-scale solar plants', 'Multi-year operations & maintenance services for two 150 MW photovoltaic plants: preventive and corrective maintenance, module cleaning, thermographic inspections, spare-parts management and 24/7 monitoring handover.', 'maintenance', 'STANDARD', 'cms5am36d000d901geopp75qf', 'Argentina', 'AR', NULL, 6000000, 10000000, '2026-09-20 00:00:00', '["O&M portfolio above 300 MW PV","Certified HV switching personnel","CMMS-based maintenance reporting"]', 'OPEN', 351, '2026-07-28 23:34:33.153', '2026-07-28 23:34:33.153');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37o000z901glr9cckpk', 'ag-epc-crushing-conveyor', 'EPC turnkey — primary crushing & overland conveyor (2,800 t/h)', 'Full EPC package for a 2,800 t/h primary crushing station and a 7.4 km overland conveyor serving an iron ore expansion in Minas Gerais: engineering, procurement, civil works, structural and electromechanical erection, commissioning and performance tests. Lump-sum turnkey with liquidated damages on schedule and throughput.', 'epc', 'EPC_TENDER', 'cms5am366000a901gonfddbnq', 'Brazil', 'BR', 'Belo Horizonte', 120000000, 180000000, '2026-12-01 00:00:00', '["Turnkey EPC references above USD 100M in mining","In-house structural & electromechanical erection capacity","Performance-test guarantees (throughput and availability)","ISO 9001 / ISO 45001 certified"]', 'OPEN', 339, '2026-07-28 23:34:33.156', '2026-07-28 23:34:33.156');
INSERT INTO public."Need" (id, slug, title, description, category, kind, "companyId", country, "countryCode", city, "budgetMin", "budgetMax", deadline, requirements, status, views, "createdAt", "updatedAt") VALUES ('cms5am37r0011901gsdlscm6j', 'tlp-geotech-survey-closed', 'Geotechnical survey campaign — coastal section', 'Completed campaign of 240 boreholes and geophysical lines along the coastal section of the water transport system. Published for reference; applications are closed.', 'technical_services', 'STANDARD', 'cms5am35v0007901g8lqs0wav', 'Chile', 'CL', NULL, 1500000, 3000000, NULL, '["Offshore/coastal drilling experience"]', 'CLOSED', 347, '2026-07-28 23:34:33.159', '2026-07-28 23:34:33.159');
