INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am391001o901g2d7kj3t3', 'cms5am36y000l901g9a7h12rd', 'cms5am38a001a901gizpy3v97', NULL, 'We operate SPMT capacity up to 320 t and maintain permanent route-engineering teams on the Chile–Argentina corridors. We propose a dedicated framework crew with port handling at Santos and Antofagasta, including escorted convoys and insurance to USD 25M per shipment.', 11500000, 'Mobilization 45 days from award', 'PENDING', '2026-07-28 23:34:33.205', '2026-07-28 23:34:33.205');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am397001q901gy4gazksw', 'cms5am37h000v901go780ru17', 'cms5am38a001a901gizpy3v97', NULL, 'Our transformer transport record includes twelve units up to 260 t delivered in the Andes. For Manzanillo–central Mexico we would partner with our Mexican JV fleet, providing SPMT, route reinforcement design and cranage under a single contract.', 8900000, 'First delivery window within 90 days', 'IN_DISCUSSION', '2026-07-28 23:34:33.211', '2026-07-28 23:34:33.211');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39b001s901gue1xpnep', 'cms5am36u000j901gb1wfl94l', 'cms5am3840017901g6n9qcfng', NULL, 'Skanor has delivered four high-head pumping stations under FIDIC Yellow Book, including SCADA integration and surge analysis. We propose a Peru-based consortium with local civil capacity and our Madrid engineering center leading process design.', 118000000, '32-month program', 'PENDING', '2026-07-28 23:34:33.215', '2026-07-28 23:34:33.215');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39f001u901ghbun03q6', 'cms5am376000p901gm7alpch3', 'cms5am38h001d901g0f1cxv3x', NULL, 'We can supply forty 96 t class trucks with a 5-year MARC guaranteeing 88% availability, on-site parts warehouse and operator training. Structured as lease-to-own with quarterly performance reviews.', 62000000, 'First 10 units in 120 days', 'PENDING', '2026-07-28 23:34:33.22', '2026-07-28 23:34:33.22');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39j001w901giqbein51', 'cms5am37a000r901gkhzvlo1d', 'cms5am38m001g901gltu6fx1l', NULL, 'Verdant led the EIA and licensing for two container-terminal expansions including dredging permits and marine biota programs. We propose a full scope: baseline studies, agency management, and a 36-month monitoring plan.', 3400000, 'Licensing package in 14 months', 'ACCEPTED', '2026-07-28 23:34:33.224', '2026-07-28 23:34:33.224');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39o001y901g944s5xru', 'cms5am37k000x901gwq9yuzat', 'cms5am38s001j901gizc2gxk8', NULL, 'We currently operate 520 MW of PV in the region with certified HV crews and a 24/7 NOC. Our proposal covers preventive/corrective maintenance, robotic module cleaning and CMMS reporting with guaranteed response times.', 7800000, 'Takeover in 60 days', 'PENDING', '2026-07-28 23:34:33.228', '2026-07-28 23:34:33.228');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39t0020901gsqz21okc', 'cms5am37o000z901glr9cckpk', 'cms5am3840017901g6n9qcfng', NULL, 'Skanor proposes a lump-sum turnkey execution with engineering from our Madrid center, local civil and erection subcontracting under our direct supervision, and guaranteed performance tests at 2,800 t/h. Schedule: 26 months with early procurement of long-lead crusher and conveyor drives.', 152000000, '26-month turnkey program', 'PENDING', '2026-07-28 23:34:33.233', '2026-07-28 23:34:33.233');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am39w0022901gllp7gbhj', 'cms5am372000n901g1ln7cg6k', 'cms5am37x0014901g40cllxmu', NULL, 'Andina can provide the drilling-support scope of the earthworks package: production drilling, geotechnical instrumentation and slope monitoring with three rigs dedicated to the site for the full 30-month program.', 9200000, 'Rigs on site 30 days from award', 'IN_DISCUSSION', '2026-07-28 23:34:33.237', '2026-07-28 23:34:33.237');
INSERT INTO public."SupplierApplication" (id, "needId", "supplierId", "consortiumId", message, "proposedBudget", "leadTime", status, "createdAt", "updatedAt") VALUES ('cms5am3a7002a901gq6zjvc6g', 'cms5am36m000h901gddwpzkeq', 'cms5am38h001d901g0f1cxv3x', 'cms5am3a20024901gyr8onynj', 'Joint bid covering the full scope: MaquiSur sources API 5L X70 pipe through its certified mill network with third-party inspection at origin; TransAndes executes port handling and staged overland deliveries to both laydown yards; Skanor provides field welding procedures and installation supervision. Single point of accountability through the consortium leader.', 72000000, 'First deliveries 5 months from award, 22-month program', 'PENDING', '2026-07-28 23:34:33.248', '2026-07-28 23:34:33.248');
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ab002c901g9pl6rvgb', 'atacama-blue-desalination-plant', 'Atacama Blue Desalination Plant', 'Operating 1,050 l/s reverse-osmosis desalination plant with long-term take-or-pay contracts supplying mining operations in northern Chile.', 'Atacama Blue is one of the largest privately held desalination assets in the Antofagasta region. Commissioned in 2019, the plant produces up to 1,050 litres per second of industrial-quality water, delivered through a 62 km pipeline network to three tier-one mining customers under take-or-pay contracts with a weighted remaining life of 14 years.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3an002m901gcai6f4sh', 'vizcachas-copper-project', 'Vizcachas Copper Project', 'Advanced-exploration copper project with 480 Mt inferred resource at 0.52% Cu, 40 km from existing rail and power infrastructure.', 'The Vizcachas Copper Project covers 8,200 hectares of highly prospective porphyry copper ground in Chile''s Coquimbo region. Since 2018, over 68,000 metres of drilling have defined an inferred resource of 480 Mt at 0.52% Cu with a 0.2% cut-off, including a higher-grade core of 120 Mt at 0.71% Cu.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3at002v901gcagim4q9', 'magallanes-green-hydrogen-ammonia', 'Magallanes Green Hydrogen & Ammonia Complex', 'Utility-scale green hydrogen-to-ammonia project in southern Chile with 1.4 GW wind resource, port access and completed pre-feasibility.', 'This project will convert Magallanes'' world-class wind resource — capacity factors above 55% — into green ammonia for export to Europe and Asia. The development comprises 1.4 GW of onshore wind, 850 MW of electrolysis, an ammonia synthesis loop of 720 ktpa, and a dedicated export terminal on the Strait of Magellan.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3az0033901glc9xqwqq', 'huayra-zinc-copper-mine', 'Huayra Zinc-Copper Mine', 'Producing underground zinc-copper mine in central Peru — 1.8 Mtpa throughput, US$74M EBITDA, 11-year reserve life.', 'Huayra is an established underground polymetallic operation in Peru''s prolific central belt, in continuous production since 2009. The mine processes 1.8 Mtpa through a conventional crush-grind-flotation circuit producing separate zinc and copper concentrates, with silver credits.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3b5003b901gjaijhua9', 'ica-valley-agro-export-platform', 'Ica Valley Agro-Export Platform', 'Vertically integrated blueberry and avocado producer-exporter with 1,850 planted hectares, packing plant and US/EU retail programs.', 'This platform consolidates three contiguous agricultural estates in Peru''s Ica valley into one of the country''s most efficient fresh-produce exporters. The operation manages 1,850 planted hectares — 1,050 of blueberries and 800 of Hass avocado — supported by a 28,000 m² packing facility with 14 processing lines, cold storage for 6,200 pallets, and senior water rights supplemented by 42 licensed wells.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3bb003j901gf8uhwb58', 'bajio-automotive-components-plant', 'Bajío Automotive Components Plant', 'Tier-1 aluminum die-casting and machining plant in Mexico''s Bajío corridor — USMCA-positioned, 92% capacity utilization, blue-chip OEM contracts.', 'Strategically located in Querétaro''s automotive corridor, this Tier-1 supplier produces high-pressure aluminum die-cast structural components and precision-machined assemblies for North American OEM platforms. The 42,000 m² facility operates 11 die-casting cells (400–2,700 t) and 38 CNC machining centers, holding IATF 16949 and ISO 14001 certifications.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3bh003r901gvfm9m18r', 'sonora-solar-park-210mw', 'Sonora Solar Park — 210 MW', 'Operating 210 MWac solar PV plant in Sonora with hybrid PPA structure, P50 generation of 585 GWh/year and repowering upside.', 'Commissioned in 2021, Sonora Solar Park spans 640 hectares of high-irradiance desert with a P50 yield of 585 GWh per year. The plant operates under a hybrid revenue structure: 70% of output is contracted under a 15-year USD-denominated PPA with an investment-grade industrial offtaker, and the remainder is sold at node prices that have averaged above PPA levels for the past three years.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3bm003z901gsrbo0nl7', 'desert-gateway-data-center-campus', 'Desert Gateway Data Center Campus', '300 MW hyperscale-ready data center campus under construction in Arizona — powered land, water-neutral cooling, first 60 MW pre-leased.', 'Desert Gateway is a 120-acre data center campus in the Phoenix metro area, one of North America''s fastest-growing digital infrastructure markets. The project holds a signed 300 MW power capacity agreement with the local utility — with 90 MW deliverable in 2027 — and a fully entitled site with completed grading and utility corridors.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3e3006c901g8gnndauu', 'cascadia-hydro-portfolio', 'Cascadia Run-of-River Hydro Portfolio', 'Three operating run-of-river hydro plants in British Columbia totalling 94 MW, fully contracted under long-term utility EPAs.', 'The portfolio comprises three run-of-river facilities commissioned between 2014 and 2017, delivering a combined 385 GWh annually under electricity purchase agreements with the provincial utility extending to 2054 on average. All plants are remotely operated from a shared control center with availability above 96%.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3br0047901gh2o16orb', 'andalucia-solar-portfolio-240mw', 'Andalucía Solar Portfolio — 240 MW', 'Four operating solar PV plants across southern Spain totalling 240 MW, blend of regulated revenues and merchant with PPA floor.', 'This portfolio aggregates four utility-scale photovoltaic plants across Seville, Córdoba and Jaén provinces, all grid-connected between 2020 and 2023. Combined P50 output is 468 GWh per year, with irradiance among the highest in continental Europe.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3bx004f901gi0izmts7', 'valencia-cold-chain-terminal', 'Valencia Agrifood Cold-Chain Terminal', 'Port-adjacent refrigerated logistics terminal serving Mediterranean agrifood exports — 38,000 pallet positions, 96% occupancy, rail siding.', 'Located 1.8 km from the Port of Valencia''s container terminals, this cold-chain logistics platform is a critical node for Spanish and North African fresh produce flowing to European markets. The facility offers 38,000 pallet positions across five temperature regimes, 42 loading docks, on-site customs and border inspection posts, and a private rail siding with daily reefer services.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3c3004m901gizn7gaey', 'fujairah-bulk-liquids-terminal', 'Fujairah Bulk Liquids Terminal', 'Operating bulk liquids storage terminal at the Port of Fujairah — 480,000 m³ capacity, deep-water jetty access, take-or-pay storage contracts.', 'Positioned at the world''s second-largest bunkering hub outside the Strait of Hormuz, this terminal provides 480,000 m³ of storage across 34 tanks for clean petroleum products, biofuels and chemicals. The asset enjoys deep-water jetty access for vessels up to Suezmax, direct pipeline connectivity to the port''s common-user infrastructure, and land reserved for a 120,000 m³ expansion.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3c8004u901gdxvzn5mx', 'pilbara-west-lithium-project', 'Pilbara West Lithium Project', 'Hard-rock lithium project in Western Australia entering construction — 41 Mt at 1.32% Li₂O, binding offtake for 60% of production.', 'Pilbara West is a construction-ready spodumene project in Western Australia''s premier lithium district. The 2025 Definitive Feasibility Study defines ore reserves of 41 Mt at 1.32% Li₂O supporting a 2.4 Mtpa concentrator producing approximately 340 ktpa of SC5.5 concentrate over a 14-year initial mine life.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ce0052901gj8dxe9hi', 'riverina-almond-estate', 'Riverina Almond Estate & Processing', '3,400-hectare almond orchard portfolio in NSW with on-site hulling and processing, 19 GL secure water entitlements included.', 'One of Australia''s largest privately held almond platforms, the Riverina Estate comprises 3,400 planted hectares across three properties in New South Wales'' Murrumbidgee region, with an average orchard age of nine years — entering peak yield. The sale includes 19 GL of high-security water entitlements, an on-site hulling and shelling complex rated at 28,000 t/year, and biomass energy generation from shell waste.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ck005a901g49wvqvb8', 'casablanca-atlantic-industrial-park', 'Casablanca Atlantic Industrial Park', '220-hectare industrial and logistics park in expansion near Casablanca — 74% leased, free-zone status, anchor tenants in automotive and textiles.', 'Casablanca Atlantic is an established industrial park 28 km from the Port of Casablanca and 19 km from Mohammed V International Airport, at the heart of Morocco''s manufacturing corridor. Phase 1 and 2 (140 ha) are 74% leased to 38 tenants including European automotive component makers, textile exporters and regional 3PLs, benefiting from free-zone tax status and on-site customs.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3cp005h901gyfvskc4q', 'patagonia-wind-farm-repowering', 'Patagonia Wind Farm Repowering', 'Repowering of an existing 48 MW wind farm in Argentine Patagonia to 120 MW with new-generation turbines.', 'Repowering opportunity for a 2009-vintage wind farm in Chubut province. The project replaces 32 legacy turbines with 20 modern 6 MW units, using existing grid connection rights, roads and substations. Wind resource is measured at 10.4 m/s average. The sponsor seeks capital for the US$140M repowering program.', 'energy', 'Argentina', 'AR', 'Comodoro Rivadavia', 'Chubut', -45.86, -67.48, 'expansion', 'capital_raise', 'IN_REVIEW', false, false, 100000000, 140000000, NULL, NULL, '120 MW post-repowering', NULL, 'Existing generation license · grid rights retained', NULL, NULL, '["Existing grid connection and land rights","10.4 m/s measured wind resource","Brownfield permitting advantage"]', '[{"label":"Current capacity","value":"48 MW (2009 COD)"},{"label":"Target capacity","value":"120 MW"}]', 0, NULL, NULL, '2026-07-28 23:34:33.337', '2026-07-28 23:34:33.337', 'cms5am35j0003901gd4ps995p');
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ds0064901gqs4bt9s9', 'parana-grain-terminal', 'Paraná River Grain Terminal', 'Operating grain export terminal on the Paraná waterway — 3.2 Mt annual throughput, on-dock storage for 240,000 t, expansion permit granted.', 'Strategically positioned river terminal serving Argentina''s core soy and corn belt, with 3.2 Mt of annual throughput, two loading berths for Panamax vessels and rail plus truck reception. On-dock silos store 240,000 tonnes, and a granted expansion permit allows a third berth and 120,000 t of additional capacity.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3dy0068901geojjyeso', 'salar-norte-lithium-brine', 'Salar Norte Lithium Brine Project', 'Advanced lithium brine project in the Argentine Puna — 2.1 Mt LCE resource, pilot DLE plant operating, seeking construction capital.', 'Salar Norte hosts a measured and indicated resource of 2.1 Mt LCE at 512 mg/L average lithium concentration, with low impurity ratios suited to direct lithium extraction. A 500 tpa DLE pilot has operated for 18 months, producing battery-grade carbonate samples that have passed initial qualification with two cathode makers.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3e9006g901gzslsoosf', 'magdalena-agroindustrial-platform', 'Magdalena Palm Oil & Biogas Platform', 'Integrated sustainable palm oil producer in Colombia — 9,800 planted hectares, RSPO-certified mill, biogas capture generating 4 MW.', 'Vertically integrated palm platform in Colombia''s Magdalena Medio: 9,800 planted hectares (own and associated growers), a 45 t/h RSPO-certified extraction mill, and a biogas capture system generating 4 MW that covers the operation''s full power demand with surplus sold to the grid.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ee006k901gwpst2ye0', 'monterrey-industrial-park-nearshoring', 'Monterrey Nearshoring Industrial Park', 'Class-A industrial park in Nuevo León — 92% leased, 310,000 m² GLA, land bank for 180,000 m² more in Mexico''s hottest corridor.', 'Class-A park in the Monterrey–Saltillo corridor with 310,000 m² of GLA across 14 buildings, 92% leased to multinational tenants in automotive, electronics and appliances under USD-denominated triple-net leases (WALT 7.2 years). The adjacent land bank supports 180,000 m² of build-to-suit expansion with utilities in place.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ej006o901ghn8ggylg', 'iberia-wind-repowering-portfolio', 'Iberia Wind Repowering Portfolio — 180 MW', 'Operating Spanish wind portfolio with locked-in repowering rights: 180 MW today, 265 MW post-repowering on the same grid connections.', 'Five wind farms across Aragón and Castilla y León commissioned 2004–2008, fully merchant since tariff expiry, with grid connection rights preserved for repowering to 265 MW using modern turbines. Repowering permits are at an advanced stage for three of the five sites.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3eo006s901gqd4xewjx', 'red-sea-desalination-ppp', 'Red Sea Coast Desalination PPP', 'Greenfield 450,000 m³/day SWRO desalination PPP with a 25-year government offtake, tendered and awarded — seeking equity co-investors.', 'Awarded public-private partnership for a 450,000 m³/day sea-water reverse-osmosis plant serving urban and industrial demand on the Red Sea coast, under a 25-year water purchase agreement with a sovereign counterparty, availability-based with full indexation.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3et006w901g0injmobk', 'tangier-automotive-supplier-park', 'Tangier Automotive Components Cluster', 'Manufacturing platform of three plants serving European OEMs from Morocco — wiring harnesses, injection molding and stamping, 3,400 employees.', 'Integrated Tier-2 automotive platform in the Tangier free zone: wiring harnesses, technical injection molding and precision stamping across three plants, exporting 96% of output to European OEM programs with 48-hour logistics to Spain.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3ey0070901g2utuksi1', 'queensland-copper-gold-mine', 'Queensland Copper-Gold Restart Project', 'Fully permitted brownfield copper-gold mine on care & maintenance — 480 kt of contained Cu equivalent remaining, restart study complete.', 'Past-producing underground copper-gold mine in North Queensland placed on care and maintenance in 2020 at the pit-to-underground transition. The 2025 restart study defines a 9-year plan producing 28 kt CuEq annually with USD 95M of restart capital, using the existing 1.1 Mtpa plant, camp and grid connection.
INSERT INTO public."Project" (id, slug, title, summary, description, category, country, "countryCode", city, region, lat, lng, stage, "dealType", status, verified, featured, "investmentMin", "investmentMax", revenue, ebitda, capacity, production, permits, workforce, "areaHectares", highlights, specs, views, "rejectionReason", "publishedAt", "createdAt", "updatedAt", "ownerId") VALUES ('cms5am3f40074901grnyi57qm', 'sao-paulo-cold-storage-network', 'São Paulo Cold Storage Network', 'Four-site temperature-controlled logistics network serving Brazil''s largest consumption market — 96,000 pallet positions, blue-chip 3PL contracts.', 'Cold-chain network across greater São Paulo and Campinas: 96,000 pallet positions in four facilities, all within 90 minutes of the city center, serving food producers, importers and quick-commerce platforms under take-or-pay and dedicated-space contracts.
