INSERT INTO public."Offer" (id, "projectId", "investorId", amount, type, "equityPct", message, status, "createdAt", "updatedAt") VALUES ('cms5am3d7005r901g69iwrb32', 'cms5am3ab002c901g9pl6rvgb', 'cms5am35n0004901g2gfut99y', 135000000, 'equity_stake', 55, 'Northbridge Infrastructure Fund is pleased to submit this non-binding expression of interest for a 55% equity stake, subject to confirmatory due diligence. We have completed three water infrastructure transactions in LatAm since 2022 and can move to binding terms within 60 days of data room access.', 'IN_DISCUSSION', '2026-07-28 23:34:33.355', '2026-07-28 23:34:33.355');
INSERT INTO public."Offer" (id, "projectId", "investorId", amount, type, "equityPct", message, status, "createdAt", "updatedAt") VALUES ('cms5am3d9005t901gq9zs4jsn', 'cms5am3bh003r901gvfm9m18r', 'cms5am35n0004901g2gfut99y', 178000000, 'full_acquisition', NULL, 'We propose a full acquisition at the indicated valuation midpoint, financed 60/40 debt-equity with committed financing letters available. Exclusivity of 45 days requested.', 'PENDING', '2026-07-28 23:34:33.358', '2026-07-28 23:34:33.358');
