INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3ff007a901ga28szebf', 'latam-water-infrastructure-mandate', 'LatAm Water & Desalination Platform Build-up', 'Northbridge Infrastructure Fund is deploying its third fund into water infrastructure across Latin America. We target operating desalination plants, water transmission and industrial water-supply assets with contracted, USD-denominated revenues. Preference for majority stakes alongside proven local operators; single-asset tickets of USD 80–250M with capacity to fund expansions.', 'cms5am35n0004901g2gfut99y', '["water"]', '["CL","PE","MX"]', '["operating","expansion"]', '["partial_sale","full_sale"]', 80000000, 250000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-28 23:34:33.435', '2026-07-28 23:34:33.435');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3fk007c901g2ktplyjn', 'copper-battery-metals-mandate', 'Copper & Battery Metals — Development Capital', 'Pacific Rim Strategic Holdings seeks copper and lithium exposure across the Americas and Australia, from advanced exploration through construction. We provide staged development capital, streaming structures or outright acquisition, with technical teams able to move to binding terms within 90 days. Ticket range USD 100–500M.', 'cms5am3fc0078901gbymbj34x', '["mining"]', '["CL","PE","AU","US"]', '["greenfield","construction","operating"]', '["capital_raise","full_sale","partial_sale"]', 100000000, 500000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-28 23:34:33.44', '2026-07-28 23:34:33.44');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3fn007e901gq2kalfca', 'iberia-latam-renewables-yield-mandate', 'Operating Renewables — Iberia & Mexico Yield Portfolio', 'Baltica Infrastructure Partners is acquiring operating solar and wind assets in Spain and Mexico for a yield-focused permanent-capital vehicle. Contracted or partially contracted revenue profiles preferred; tickets of USD 100–300M per transaction, with appetite for portfolios up to USD 600M.', 'cms5am3f90077901ghm3brjnn', '["energy"]', '["ES","MX"]', '["operating"]', '["full_sale","partial_sale"]', 100000000, 300000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-28 23:34:33.444', '2026-07-28 23:34:33.444');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3fr007g901g6lk4fgug', 'green-hydrogen-jv-mandate', 'Green Hydrogen & Ammonia — Strategic JV Partner', 'Industrial group with committed offtake in Northern Europe seeks joint-venture positions in utility-scale green hydrogen and ammonia projects with world-class renewable resources. We contribute FEED funding, offtake and engineering capacity for projects targeting FID within 4 years. Investment capacity of USD 500M–1.5B per platform.', 'cms5am3f90077901ghm3brjnn', '["energy"]', '["CL","MA","AU"]', '["greenfield","construction"]', '["joint_venture","capital_raise"]', 500000000, 1500000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-28 23:34:33.447', '2026-07-28 23:34:33.447');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3fu007i901gm9xpv8zs', 'agro-export-platforms-mandate', 'Export Agriculture Platforms — Growth Equity', 'Pacific Rim Strategic Holdings allocates growth equity to vertically integrated agro-export platforms with secured water rights and retail programs in premium markets. Berries, avocado, nuts and permanent crops preferred; tickets USD 30–250M for minority or control positions.', 'cms5am3fc0078901gbymbj34x', '["agro"]', '["PE","CL","MX","AU"]', '["operating","expansion"]', '["capital_raise","partial_sale","full_sale"]', 30000000, 250000000, NULL, NULL, NULL, true, 'PUBLISHED', NULL, '2026-07-28 23:34:33.45', '2026-07-28 23:34:33.45');
INSERT INTO public."Mandate" (id, slug, title, description, "investorId", categories, countries, stages, "dealTypes", "ticketMin", "ticketMax", "equityMin", "equityMax", conditions, "isPublic", status, "rejectionReason", "createdAt", "updatedAt") VALUES ('cms5am3fx007k901g0rwcljk9', 'core-ports-logistics-confidential', 'Core+ Ports & Terminals — Confidential Search', 'On behalf of a sovereign-adjacent investor, Northbridge is conducting a confidential search for operating port terminals and cold-chain logistics assets in Southern Europe and the Gulf. Take-or-pay or contracted revenue required; tickets USD 50–250M. This mandate is not publicly listed.', 'cms5am35n0004901g2gfut99y', '["ports"]', '["ES","AE"]', '["operating"]', '["partial_sale","full_sale"]', 50000000, 250000000, NULL, NULL, NULL, false, 'PUBLISHED', NULL, '2026-07-28 23:34:33.453', '2026-07-28 23:34:33.453');
