INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3g4007n901ginacpe9g', 'grade-a-copper-cathodes-antofagasta', 'SELL', 'copper_cathodes', 'Grade A Copper Cathodes — 2,000 t/month, FOB Antofagasta', 'LME-registered Grade A copper cathodes (99.9935% Cu) produced at an established electro-winning operation in northern Chile. Consistent monthly availability of 2,000 tonnes with capacity to scale to 3,000 tonnes under an annual frame contract. Full traceability, ISO 9001 production and certificates of analysis issued by an independent laboratory for every lot.', '[{"label":"Purity","value":"99.9935% Cu (LME Grade A)"},{"label":"Format","value":"Cathode sheets, ~125 kg, steel-strapped bundles"},{"label":"Registration","value":"LME-registered brand"},{"label":"Packing","value":"Bundles of ~2.2 t"}]', '2,000 t/month', 'contract', 'CL', NULL, 'FOB', 'Port of Antofagasta, Chile', 'indexed', 'LME Cash Settlement minus 45 USD/t', NULL, '[{"name":"Certificate of Analysis (sample lot)","url":"https://example.com/docs/sample.pdf","isConfidential":true},{"name":"Product Specification Sheet","url":"https://example.com/docs/sample.pdf","isConfidential":false}]', 'PUBLISHED', true, NULL, 640, 'cms5am35e0002901gjctmfvd4', '2026-07-28 23:34:33.46', '2026-07-28 23:34:33.46');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3g9007p901gtoqvqk7u', 'copper-concentrate-26-southern-peru', 'SELL', 'copper_concentrate', 'Copper Concentrate 26% Cu — 10,000 t/quarter, CIF Main Asian Port', 'Clean copper concentrate from a producing mine in southern Peru: 26% Cu with gold and silver credits, low arsenic (<0.15%). Quarterly parcels of 10,000 wmt under an annual offtake frame, shipped in bulk from Matarani. Standard TC/RC terms with quotational period negotiable.', '[{"label":"Cu grade","value":"26% (typical)"},{"label":"Au / Ag credits","value":"3.1 g/t Au · 68 g/t Ag"},{"label":"Arsenic","value":"<0.15%"},{"label":"Moisture","value":"8.5%"}]', '10,000 wmt/quarter', 'contract', 'PE', NULL, 'CIF', 'Main Asian port (buyer''s option)', 'indexed', 'LME basis, benchmark TC/RC, QP M+1', NULL, '[{"name":"Typical Assay Certificate","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 512, 'cms5am3590001901gxvwc1t0y', '2026-07-28 23:34:33.465', '2026-07-28 23:34:33.465');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gc007r901gz3n64vp4', 'battery-grade-lithium-carbonate-chile', 'SELL', 'lithium_carbonate', 'Battery-Grade Lithium Carbonate — 300 t/month, FOB Chilean Port', 'Battery-grade lithium carbonate (≥99.5% Li₂CO₃) from brine operations in the Atacama basin. Monthly availability of 300 tonnes in 500 kg big bags, containerized. Suitable for cathode manufacturing; magnetic impurities controlled below 300 ppb. Long-term supply contracts preferred; spot parcels considered.', '[{"label":"Purity","value":"≥99.5% Li₂CO₃"},{"label":"Magnetic impurities","value":"<300 ppb"},{"label":"Packing","value":"500 kg big bags, 20 t per container"}]', '300 t/month', 'contract', 'CL', NULL, 'FOB', 'Port of Angamos, Chile', 'indexed', 'Fastmarkets Li₂CO₃ CIF Asia index minus 3%', NULL, '[{"name":"Battery-Grade Specification","url":"https://example.com/docs/sample.pdf","isConfidential":false},{"name":"Full Impurity Panel (CoA)","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 738, 'cms5am35e0002901gjctmfvd4', '2026-07-28 23:34:33.469', '2026-07-28 23:34:33.469');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gg007t901g1pfryk1c', 'iron-ore-fines-62-port-hedland', 'SELL', 'iron_ore', 'Iron Ore Fines 62% Fe — 50,000 t Spot Parcels, FOB Port Hedland', 'Standard 62% Fe iron ore fines available in spot parcels of 50,000 tonnes from Port Hedland. Low phosphorus and alumina; sized 0–10 mm. Immediate laycans available; larger contract volumes negotiable for H2.', '[{"label":"Fe content","value":"62% (typical)"},{"label":"Sizing","value":"0–10 mm fines"},{"label":"Phosphorus","value":"0.07%"},{"label":"Alumina","value":"2.1%"}]', '50,000 t/parcel (spot)', 'spot', 'AU', NULL, 'FOB', 'Port Hedland, Australia', 'indexed', 'Platts IODEX 62% Fe minus 2.5 USD/t', NULL, '[]', 'PUBLISHED', true, NULL, 431, 'cms5am35j0003901gd4ps995p', '2026-07-28 23:34:33.472', '2026-07-28 23:34:33.472');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gk007v901gslwdna6l', 'molybdenum-oxide-chile', 'SELL', 'molybdenum_oxide', 'Molybdenum Oxide (Tech Grade) — 200 t/month, CIF Rotterdam', 'Technical-grade molybdenum oxide (57% Mo min) in drums, by-product of a Chilean copper operation. Monthly volume of 200 tonnes, shipped containerized to Rotterdam or main European port. Annual contract with quarterly price reviews preferred.', '[{"label":"Mo content","value":"57% min"},{"label":"Packing","value":"250 kg drums"}]', '200 t/month', 'contract', 'CL', NULL, 'CIF', 'Rotterdam, Netherlands', 'indexed', 'Platts Mo oxide mean, quarterly review', NULL, '[]', 'PUBLISHED', false, NULL, 210, 'cms5am35e0002901gjctmfvd4', '2026-07-28 23:34:33.476', '2026-07-28 23:34:33.476');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gn007x901gr1twxrwr', 'zinc-concentrate-52-callao', 'SELL', 'zinc_concentrate', 'Zinc Concentrate 52% Zn — 5,000 t/month, FOB Callao', 'High-grade zinc concentrate (52% Zn, 380 g/t Ag credits) from a producing polymetallic mine in central Peru. Monthly liftings of 5,000 wmt from Callao under annual frames; standard smelter terms.', '[{"label":"Zn grade","value":"52%"},{"label":"Ag credits","value":"380 g/t"},{"label":"Fe","value":"6.2%"}]', '5,000 wmt/month', 'contract', 'PE', NULL, 'FOB', 'Port of Callao, Peru', 'indexed', 'LME Zn basis, benchmark TC', NULL, '[{"name":"Typical Assay","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', true, NULL, 356, 'cms5am35j0003901gd4ps995p', '2026-07-28 23:34:33.479', '2026-07-28 23:34:33.479');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gr007z901gwa7q0ofu', 'gold-dore-lima', 'SELL', 'gold_dore', 'Gold Doré 92% Au — 50 kg/month, EXW Lima', 'Gold doré bars (92% Au, 6% Ag typical) from a formalized medium-scale producer in Peru, with full chain-of-custody documentation and export permits. Monthly availability of 50 kg; refining and logistics support available for qualified buyers. Compliance dossier (LBMA-aligned responsible sourcing) shared under NDA.', '[{"label":"Au content","value":"92% (typical)"},{"label":"Ag content","value":"6% (typical)"},{"label":"Bar size","value":"~12.5 kg"}]', '50 kg/month', 'contract', 'PE', NULL, 'EXW', 'Lima, Peru (secure facility)', 'indexed', 'LBMA PM fix minus 1.2%, assay-adjusted', NULL, '[{"name":"Responsible Sourcing Dossier","url":"https://example.com/docs/sample.pdf","isConfidential":true}]', 'PUBLISHED', false, NULL, 489, 'cms5am35j0003901gd4ps995p', '2026-07-28 23:34:33.483', '2026-07-28 23:34:33.483');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gu0081901gu22n80qa', 'premium-fishmeal-callao', 'SELL', 'fishmeal', 'Premium Fishmeal 67% Protein — 3,000 t/quarter, FOB Callao', 'Super-prime fishmeal (67% protein min, TVN <100) from certified Peruvian producers, IFFO RS chain of custody. Quarterly parcels of 3,000 tonnes in 50 kg bags or big bags. Annual supply programs available with fixed premium over the Peruvian export reference.', '[{"label":"Protein","value":"67% min"},{"label":"TVN","value":"<100 mg/100g"},{"label":"Certification","value":"IFFO RS"}]', '3,000 t/quarter', 'contract', 'PE', NULL, 'FOB', 'Port of Callao, Peru', 'fixed', 'USD 1,720/t FOB (current quarter)', NULL, '[]', 'PUBLISHED', true, NULL, 298, 'cms5am35j0003901gd4ps995p', '2026-07-28 23:34:33.487', '2026-07-28 23:34:33.487');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3gy0083901gj5845sys', 'bek-wood-pulp-brazil', 'SELL', 'wood_pulp', 'Bleached Eucalyptus Kraft Pulp — 8,000 t/month, FOB Santos', 'BEK market pulp from a certified Brazilian producer (FSC), 8,000 tonnes monthly in unitized bales. Suitable for tissue and printing grades. Annual contracts with quarterly volume flexibility of ±10%.', '[{"label":"Grade","value":"BEKP (bleached eucalyptus kraft)"},{"label":"Certification","value":"FSC"},{"label":"Brightness","value":"≥89% ISO"}]', '8,000 t/month', 'contract', 'BR', NULL, 'FOB', 'Port of Santos, Brazil', 'indexed', 'PIX BHKP index minus agreed discount', NULL, '[]', 'PUBLISHED', false, NULL, 187, 'cms5am35e0002901gjctmfvd4', '2026-07-28 23:34:33.49', '2026-07-28 23:34:33.49');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3h10085901g6lsnnkon', 'buy-copper-cathodes-gulf', 'BUY', 'copper_cathodes', 'Buying: Grade A Copper Cathodes — 1,500–3,000 t/month, Gulf Destination', 'Gulf Metals Trading FZE seeks Grade A copper cathodes for long-term supply into Gulf and South Asian re-rolling customers. Monthly volumes of 1,500–3,000 tonnes under 12-month frames with LCs from first-class banks. LME-registered brands preferred; non-registered considered with full assay history.', '[{"label":"Purity required","value":"99.99% Cu min"},{"label":"Payment","value":"LC at sight, first-class bank"}]', '1,500–3,000 t/month', 'contract', NULL, 'AE', 'CIF', 'Jebel Ali, UAE', 'indexed', 'LME basis plus negotiable premium', NULL, '[]', 'PUBLISHED', true, NULL, 402, 'cms5am3g0007l901gk93b4p06', '2026-07-28 23:34:33.493', '2026-07-28 23:34:33.493');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3h50087901g93oqzm3d', 'buy-lithium-carbonate-us', 'BUY', 'lithium_carbonate', 'Buying: Battery-Grade Lithium Carbonate — 200 t/month, US Cathode Plant', 'US cathode-materials manufacturer seeks battery-grade lithium carbonate under multi-year contract, 200 t/month ramping to 500 t/month by 2028. Qualification samples required; IRA-compliant origins prioritized.', '[{"label":"Purity required","value":"≥99.5% Li₂CO₃, battery grade"},{"label":"Qualification","value":"2-lot sampling process"}]', '200 t/month (ramping to 500 t)', 'contract', NULL, 'US', 'FOB', 'US Gulf port', 'indexed', 'Fastmarkets index basis, collar structure', NULL, '[]', 'PUBLISHED', true, NULL, 377, 'cms5am3fc0078901gbymbj34x', '2026-07-28 23:34:33.497', '2026-07-28 23:34:33.497');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3h80089901gf6mjtvvq', 'buy-iron-ore-fines-gulf-steel', 'BUY', 'iron_ore', 'Buying: Iron Ore Fines 62% — Spot Parcels 50,000 t, Gulf Steel Mill', 'Integrated steel producer in the Gulf seeks spot parcels of 62% Fe fines, 50,000–80,000 t per shipment, 4–6 shipments per year. Prompt laycans; payment by confirmed LC.', '[{"label":"Fe required","value":"61.5% min"}]', '50,000–80,000 t/parcel', 'spot', NULL, 'AE', 'FOB', 'Loading port at seller''s option', 'indexed', 'Platts IODEX basis', NULL, '[]', 'PUBLISHED', true, NULL, 265, 'cms5am3g0007l901gk93b4p06', '2026-07-28 23:34:33.501', '2026-07-28 23:34:33.501');
INSERT INTO public."CommodityListing" (id, slug, side, commodity, title, description, specs, volume, periodicity, "originCode", "destinationCode", incoterm, "deliveryLocation", "priceType", "priceDetails", "validUntil", documents, status, verified, "rejectionReason", views, "ownerId", "createdAt", "updatedAt") VALUES ('cms5am3hc008b901gkitxmm3h', 'buy-fishmeal-aquafeed-spain', 'BUY', 'fishmeal', 'Buying: Super-Prime Fishmeal — 2,500 t/quarter, Spanish Aquafeed Group', 'European aquafeed producer seeks super-prime fishmeal (66%+ protein) on annual programs, 2,500 tonnes quarterly, delivered FOB origin with IFFO RS certification mandatory.', '[{"label":"Protein required","value":"66% min"},{"label":"Certification","value":"IFFO RS mandatory"}]', '2,500 t/quarter', 'contract', NULL, 'ES', 'FOB', 'Origin port', 'fixed', 'Fixed quarterly, negotiable', NULL, '[]', 'PUBLISHED', false, NULL, 143, 'cms5am3f90077901ghm3brjnn', '2026-07-28 23:34:33.504', '2026-07-28 23:34:33.504');
